def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0)

    # Network referral rule: self_employed applicant with requested_limit
    # strictly above 6000 must go to manual review (unless it's a decline).
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000
            and decision != "decline"):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "decline":
        return {"action": "decline", "limit": 0}
    # decision == "refer"
    return {"action": "queue_review", "limit": 0}
